using namespace std;

const int MAX = 100000000;
const int Is = 110;

int dik(int s, int g, int n, const vector<vector<int>>& map) {
    vector<int> cost(Is, MAX);
    vector<bool> visited(Is, false);
    cost[s] = 0;

    for (int i = 0; i < n; i++) {
        int min_cost = MAX, min_index = -1;
        for (int j = 0; j < Is; j++) {
            if (!visited[j] && cost[j] < min_cost) {
                min_cost = cost[j];
                min_index = j;
            }
        }
        if (min_index == -1) break;
        visited[min_index] = true;

        for (int j = 0; j < Is; j++) {
            if (map[min_index][j] != MAX && cost[j] > cost[min_index] + map[min_index][j]) {
                cost[j] = cost[min_index] + map[min_index][j];
            }
        }
    }
    return cost[g] == MAX ? -1 : cost[g]; // Return -1 if not reachable
}

int main() {
    int n, k, req, a, b, c, d, e, ans;
    while (cin >> n >> k, n != 0 || k != 0) {
        vector<vector<int>> map(Is, vector<int>(Is, MAX));

        while (k--) {
            cin >> req;
            if (req) {
                cin >> c >> d >> e;
                map[c][d] = map[d][c] = min(map[c][d], e); // Use min directly
            } else {
                cin >> a >> b;
                if ((ans = dik(a, b, n, map)) != MAX) cout << ans << endl;
                else cout << "-1" << endl;
            }
        }
    }
    return 0;
}
